2816	  p.k_descale = kd ? (const float*)kd->data_ptr() : nullptr;
2817	  p.v_descale = vd ? (const float*)vd->data_ptr() : nullptr;
2818	  // Descale strides IN ELEMENTS (broadcast-safe: a (b,hkv) tensor with stride [0,0] -> 0,0).
2819	  p.ds_b = qd ? (int)qd->stride(0) : 0;
2820	  p.ds_h = qd ? (int)qd->stride(1) : 0;
2821	  p.q_row = q.stride(0); p.q_head = q.stride(1);
2822	  // k/v paged (nblocks, block, hkv, hd): index krow over flattened (blk*block_size+off),
2823	  // so row stride = stride(1), head stride = stride(2). Non-paged: row stride(0), head stride(1).
2824	  if (page_table) { p.k_row = k.stride(1); p.k_head = k.stride(2); p.v_row = v.stride(1); p.v_head = v.stride(2); }
2825	  else            { p.k_row = k.stride(0); p.k_head = k.stride(1); p.v_row = v.stride(0); p.v_head = v.stride(1); }
2826	  p.o_row = out.stride(0); p.o_head = out.stride(1);
2827	  p.b = b; p.hq = hq; p.hkv = hkv; p.hd = hd; p.hdv = hdv; p.total_q = total_q;
2828	  p.scale = (float)scale; p.softcap = (float)softcap; p.win_l = win_l; p.win_r = win_r; p.causal = causal;
2829	  long pairs = (long)total_q * hq;
2830	  int threads = 128; long warps_per_block = threads / 32;
2831	  long blocks = (pairs + warps_per_block - 1) / warps_per_block;
2832	  attn_kernel<TIn, TOut><<<(unsigned)blocks, threads, 0, stream>>>(p);
2833	}
2834	
2835	static int mha_num_sm() {
2836	  static int num_sm = 0;
2837	  if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
2838	  return num_sm;
2839	}
