2841	std::vector<at::Tensor> mha_fwd(
2842	    at::Tensor q, at::Tensor k, at::Tensor v,
2843	    std::optional<at::Tensor> k_new, std::optional<at::Tensor> v_new, std::optional<at::Tensor> q_v,
2844	    std::optional<at::Tensor> out_,
2845	    std::optional<at::Tensor> cu_seqlens_q, std::optional<at::Tensor> cu_seqlens_k, std::optional<at::Tensor> cu_seqlens_k_new,
2846	    std::optional<at::Tensor> seqused_q, std::optional<at::Tensor> seqused_k,
2847	    std::optional<int64_t> max_seqlen_q, std::optional<int64_t> max_seqlen_k,
2848	    std::optional<at::Tensor> page_table, std::optional<at::Tensor> kv_batch_idx, std::optional<at::Tensor> leftpad_k,
2849	    std::optional<at::Tensor> rotary_cos, std::optional<at::Tensor> rotary_sin, std::optional<at::Tensor> seqlens_rotary,
2850	    std::optional<at::Tensor> q_descale, std::optional<at::Tensor> k_descale, std::optional<at::Tensor> v_descale,
2851	    double softmax_scale, bool is_causal, int64_t window_size_left, int64_t window_size_right,
2852	    double softcap, bool is_rotary_interleaved,
2853	    std::optional<at::Tensor> scheduler_metadata, int64_t num_splits, std::optional<bool> pack_gqa, int64_t sm_margin,
2854	    std::optional<at::Tensor> s_aux, int64_t cp_world_size, int64_t cp_rank, std::optional<at::Tensor> cp_tot_seqused_k) {
2855	  const at::cuda::OptionalCUDAGuard guard(q.device());
2856	  auto stream = at::cuda::getCurrentCUDAStream();
2857	
2858	  int total_q = (int)q.size(0);
2859	  int hq = (int)q.size(1);
2860	  int hd = (int)q.size(2);
2861	  bool paged = page_table.has_value();
2862	  int hkv = paged ? (int)k.size(2) : (int)k.size(1);
2863	  int hdv = paged ? (int)v.size(3) : (int)v.size(2);
2864	  int b = (int)cu_seqlens_q->size(0) - 1;
2865	
2866	  bool is_fp8 = q.scalar_type() == at::kFloat8_e4m3fn;
2867	  auto out_dtype = is_fp8 ? at::kBFloat16 : q.scalar_type();
2868	  at::Tensor out = out_.has_value() ? *out_
2869	                 : at::empty({total_q, hq, hdv}, q.options().dtype(out_dtype));
2870	  at::Tensor lse = at::empty({hq, total_q}, q.options().dtype(at::kFloat));
2871	
2872	  int win_l = (int)window_size_left, win_r = (int)window_size_right;
2873	  bool causal = is_causal;
2874	
2875	  // FAST PATH routing: two wgmma paths cover EVERY supported shape -- the split-KV decode kernel for
2876	  // small/medium packed-M decode/append/spec (q <= 32 AND q*rep <= 64, i.e. one DCM=64 M-tile) and the
2877	  // prefill kernel for everything else (larger q, incl. q >= 64 prompts and rep > 16 past 64 rows).
2878	  // BOTH implement softcap + sliding-window via the EXTRA template, so neither is gated at dispatch.
2879	  // `can_prefill` is defined AFTER the decode predicate below so it can defer to it (the prefill kernel
2880	  // is correct for small q too, but split-KV decode parallelizes long context that prefill cannot).
2881	  bool hd_ok = (hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256);
2882	  bool dt16_ok = (q.scalar_type() == at::kBFloat16) || (q.scalar_type() == at::kHalf);  // bf16/fp16 share layout
2883	  bool dtwg_ok = dt16_ok || is_fp8;  // wgmma fast path: bf16/fp16 native, fp8 via convert->bf16 smem + descale
2884	
2885	  // DECODE fast path: small q_len (decode/append/spec/medium-q). Flash-decoding + split-KV + combine.
2886	  // Generic over dtype (bf16/fp16/fp8 descale-folded), GQA/MQA, softcap, sliding-window, paged.
2887	  // The split-KV kernel runs the prefill mainloop with DCM=64 (one consumer warpgroup), so it packs
2888	  // up to 64 q*rep rows into ONE M-tile -- the lever it adds over prefill is splitting a long KV
2889	  // context across CTAs (+ combine), which is exactly what a small-q / long-context request needs and
2890	  // the single-CTA prefill path cannot do. Cap at max_q<=32 (keep large-q prompts q>=64 on the CM=128
2891	  // prefill path) and q*rep<=64 (one DCM tile, right-sized -- CM=128 would waste a warpgroup on masked
2892	  // rows). Requires contiguous head-dim.
2893	  bool dt_ok = (q.scalar_type() == at::kBFloat16) || (q.scalar_type() == at::kHalf) || is_fp8;
2894	  bool dhd_ok = (hd % 32 == 0) && (hdv % 32 == 0) &&
2895	                ((hd == 64 && hdv == 64) || (hd == 96 && hdv == 96) || (hd == 128 && hdv == 128) ||
2896	                 (hd == 192 && hdv == 192) || (hd == 256 && hdv == 256) || (hd == 192 && hdv == 128));
2897	  bool contig_hd = q.stride(2) == 1 &&
2898	                   (paged ? (k.stride(3) == 1 && v.stride(3) == 1) : (k.stride(2) == 1 && v.stride(2) == 1));
2899	  int rep = (hq % hkv == 0) ? hq / hkv : 0;
2900	  int max_q = max_seqlen_q.has_value() ? (int)max_seqlen_q.value() : total_q;
2901	  bool can_decode = dt_ok && dhd_ok && contig_hd && (hq % hkv == 0) &&
2902	                    max_q >= 1 && max_q <= 32 && (max_q * rep) <= 64;
2903	  int max_klen = max_seqlen_k.has_value() ? (int)max_seqlen_k.value() : 0;
2904	  // FAST decode: the wgmma prefill mainloop + split-KV (reuses TMA/async-pipelined loads, softcap+SWA).
2905	  // Limited to what that kernel supports (bf16/fp16/fp8-convert, hd==hdv in {64,128}); rest use warp path.
2906	  bool can_decode_fast = can_decode && dtwg_ok &&
2907	                         (((hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256)) ||
2908	                          (hd == 192 && hdv == 128));
2909	  // Prefill wgmma path: ANY q >= 1 that the small-q decode path does not claim. Covers q >= 64 prompts,
2910	  // the medium-q 5..63 band, and rep > 16 at small q -- the prefill kernel packs q*rep into its M tiles
2911	  // (token = row/rep, qhead = hk*rep + row%rep) with no <=16-row cap, so arbitrary q/rep are correct.
2912	  // softcap + sliding-window are handled by launch_prefill's EXTRA dispatch. Deferring via
2913	  // !can_decode_fast keeps every existing decode config on the (faster) decode kernel -> no regression.
2914	  bool can_prefill = dtwg_ok && hd_ok && (hq % hkv == 0) &&
2915	                     max_seqlen_q.has_value() && max_seqlen_q.value() >= 1 && !can_decode_fast;
2916	
2917	  // UNDERFILLED prefill -> split-KV decode. The CM=128 prefill grid is tiles_m*hkv*b CTAs (one wave,
2918	  // num_splits=1); when batch*heads*m-tiles is small over a LONG context that leaves most SMs idle and
2919	  // exposes the full DRAM latency (e.g. q120/k4224: 2*8*4 = 64 CTAs on 132 SMs -> 0.48 wave, ~0.81x).
2920	  // The split-KV decode path runs the SAME prefill mainloop at CM=64 (2x m-tiles), picks a wave-filling
2921	  // split count, and uses the deep STAGES=5 K/V pipeline -- exactly the long-context latency-hiding the
2922	  // single-wave prefill lacks. Gated to the decode-path head dims + long ctx + modest q so well-filled
2923	  // prefills (dense batch>=2, q>=256, or short ctx) are untouched (they measure better on CM=128).
2924	  int pf_tiles_m = (max_q * rep + 128 - 1) / 128;
2925	  long pf_base = (long)pf_tiles_m * (long)hkv * (long)b;
2926	  bool decode_caps = ((hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256)) ||
2927	                     (hd == 192 && hdv == 128);
2928	  bool pf_underfill = can_prefill && dhd_ok && contig_hd && decode_caps && rep >= 1 &&
2929	                      (pf_base * 2 <= (long)mha_num_sm()) && max_klen >= 2048 && max_q > 32 && max_q <= 256;
2930	
2931	  if (total_q > 0 && can_prefill && !pf_underfill) {
2932	    // descale: nullopt for bf16/fp16 (vLLM passes a stride-0 broadcast that must be IGNORED); real
2933	    // q/k/v_descale for fp8 (folded: qd*kd into the softmax scale, vd into O at the epilogue).
2934	#define PF_RT(TIN_, TC_, QD_, KD_, VD_)                                                                 \
2935	    pf::launch_prefill<TIN_, TC_>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, page_table, \
2936	        QD_, KD_, VD_, b, hq, hkv, hd, hdv, total_q, (int)max_seqlen_q.value(), softmax_scale, causal,  \
2937	        softcap, win_l, win_r, stream)
2938	    if (q.scalar_type() == at::kBFloat16) PF_RT(__nv_bfloat16, __nv_bfloat16, std::nullopt, std::nullopt, std::nullopt);
2939	    else if (q.scalar_type() == at::kHalf) PF_RT(__half, __half, std::nullopt, std::nullopt, std::nullopt);
2940	    else if (hd == 128)  // native e4m3 wgmma prefill (2x tensor throughput); hd64 fp8 -> convert path
2941	      pf::launch_prefill_fp8(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, page_table,
2942	        q_descale, k_descale, v_descale, b, hq, hkv, hd, hdv, total_q, (int)max_seqlen_q.value(),
2943	        softmax_scale, causal, softcap, win_l, win_r, stream);
2944	    else                                  PF_RT(__nv_fp8_e4m3, __nv_bfloat16, q_descale, k_descale, v_descale);
2945	#undef PF_RT
2946	  } else if (total_q > 0 && (can_decode_fast || pf_underfill)) {
2947	#define DS_DEC(TIN_, TC_, HD_, HDV_, QD_, KD_, VD_)                                                    \
2948	    launch_decode_split<TIN_, TC_, HD_, HDV_>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, \
2949	        page_table, QD_, KD_, VD_, b, hq, hkv, total_q, max_q, max_klen, (int)num_splits, softmax_scale, \
2950	        causal, softcap, win_l, win_r, stream)
2951	#define DS_RT(TIN_, TC_, QD_, KD_, VD_) do {                                                            \
2952	    if (hd == 128)                    DS_DEC(TIN_, TC_, 128, 128, QD_, KD_, VD_);                        \
2953	    else if (hd == 96)                DS_DEC(TIN_, TC_, 96, 96, QD_, KD_, VD_);                          \
2954	    else if (hd == 192 && hdv == 128) DS_DEC(TIN_, TC_, 192, 128, QD_, KD_, VD_);                       \
2955	    else if (hd == 192)               DS_DEC(TIN_, TC_, 192, 192, QD_, KD_, VD_);                       \
2956	    else if (hd == 256)               DS_DEC(TIN_, TC_, 256, 256, QD_, KD_, VD_);                       \
2957	    else                              DS_DEC(TIN_, TC_, 64, 64, QD_, KD_, VD_);                          \
2958	  } while (0)
2959	    if (q.scalar_type() == at::kBFloat16) DS_RT(__nv_bfloat16, __nv_bfloat16, std::nullopt, std::nullopt, std::nullopt);
2960	    else if (q.scalar_type() == at::kHalf) DS_RT(__half, __half, std::nullopt, std::nullopt, std::nullopt);
2961	    else if (hd == 128)  // native e4m3 wgmma decode-split (no convert pass); hd64 fp8 -> convert path
2962	      launch_decode_split_fp8<128, 128>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k,
2963	        page_table, q_descale, k_descale, v_descale, b, hq, hkv, total_q, max_q, max_klen,
2964	        (int)num_splits, softmax_scale, causal, softcap, win_l, win_r, stream);
2965	    else                                  DS_RT(__nv_fp8_e4m3, __nv_bfloat16, q_descale, k_descale, v_descale);
2966	#undef DS_RT
2967	#undef DS_DEC
2968	  } else if (total_q > 0) {
2969	    // The two wgmma paths above (split-KV decode for q<=4 & q*rep<=16; prefill for any other q>=1,
2970	    // softcap + sliding-window included) cover every q/rep/causal/window/softcap combination. Reaching
2971	    // here means the shape is outside the supported HEAD-DIM / DTYPE / LAYOUT envelope: hd==hdv in
2972	    // {64,96,128,192,256} (or 192/128 for decode), bf16/fp16/fp8-e4m3, contiguous head dim, hq%hkv==0.
2973	    TORCH_CHECK(false, "fa3-fwd: unsupported config (dtype=", q.scalar_type(), " hd=", hd, " hdv=", hdv,
2974	                " max_seqlen_q=", (max_seqlen_q.has_value() ? (int)max_seqlen_q.value() : -1),
2975	                " softcap=", softcap, " win=[", win_l, ",", win_r, "]); supported envelope: "
2976	                "hd==hdv in {64,96,128,192,256} (or 192/128 decode), bf16/fp16/fp8, contiguous, hq%hkv==0.");
2977	  }
2978	  // return [out, softmax_lse, out_accum(empty), softmax_lse_accum(empty)]
2979	  at::Tensor empty = at::empty({0}, q.options().dtype(at::kFloat));
2980	  return {out, lse, empty, empty};
2981	}
