2983	at::Tensor mha_fwd_get_scheduler_metadata(
2984	    int64_t batch_size, int64_t max_seqlen_q, int64_t max_seqlen_k, int64_t num_heads, int64_t num_heads_k,
2985	    int64_t headdim, int64_t headdim_v, at::ScalarType qkv_dtype, at::Tensor seqused_k,
2986	    std::optional<at::Tensor> cu_seqlens_q, std::optional<at::Tensor> cu_seqlens_k, std::optional<at::Tensor> cu_seqlens_k_new,
2987	    std::optional<at::Tensor> seqused_q, std::optional<at::Tensor> leftpad_k, std::optional<int64_t> page_size,
2988	    int64_t max_seqlen_k_new, bool is_causal, int64_t window_size_left, int64_t window_size_right, bool has_softcap,
2989	    int64_t num_splits, std::optional<bool> pack_gqa, int64_t sm_margin) {
2990	  // Our fwd recomputes everything internally; return a benign tensor.
2991	  return at::zeros({1}, seqused_k.options().dtype(at::kInt));
2992	}
