2994	TORCH_LIBRARY(FA3_LIB_NAME, m) {
2995	  m.def("fwd(Tensor! q, Tensor k, Tensor v, Tensor? k_new, Tensor? v_new, Tensor? q_v, "
2996	        "Tensor!? out, Tensor? cu_seqlens_q, Tensor? cu_seqlens_k, Tensor? cu_seqlens_k_new, "
2997	        "Tensor? seqused_q, Tensor? seqused_k, int? max_seqlen_q, int? max_seqlen_k, "
2998	        "Tensor? page_table, Tensor? kv_batch_idx, Tensor? leftpad_k, Tensor? rotary_cos, "
2999	        "Tensor? rotary_sin, Tensor? seqlens_rotary, Tensor? q_descale, Tensor? k_descale, "
3000	        "Tensor? v_descale, float softmax_scale, bool is_causal, int window_size_left, "
3001	        "int window_size_right, float softcap, bool is_rotary_interleaved, "
3002	        "Tensor? scheduler_metadata, int num_splits, bool? pack_gqa, int sm_margin, "
3003	        "Tensor? s_aux, int cp_world_size, int cp_rank, Tensor? cp_tot_seqused_k) -> Tensor[]");
3004	  m.impl("fwd", torch::kCUDA, &mha_fwd);
3005	  m.def("get_scheduler_metadata(int batch_size, int max_seqlen_q, int max_seqlen_k, "
3006	        "int num_heads, int num_heads_k, int headdim, int headdim_v, ScalarType qkv_dtype, "
3007	        "Tensor seqused_k, Tensor? cu_seqlens_q, Tensor? cu_seqlens_k, Tensor? cu_seqlens_k_new, "
3008	        "Tensor? seqused_q, Tensor? leftpad_k, int? page_size, int max_seqlen_k_new, "
3009	        "bool is_causal, int window_size_left, int window_size_right, bool has_softcap, "
3010	        "int num_splits, bool? pack_gqa, int sm_margin) -> Tensor");
