    constexpr int NEG = -0x40000000;                                  // -inf sentinel for "no left bound"
    const int lo0 = (win_l >= 0) ? (qlo - win_l) : NEG;
    const int lo1 = (win_l >= 0) ? (qhi - win_l) : NEG;
    int hi0 = seqlen_k - 1, hi1 = seqlen_k - 1;                       // upper bound folds in seqlen_k
