// instruction vs the ~20-instruction libdevice tanhf -- softcap feeds exp2 so approx is ample.
__device__ __forceinline__ float fast_tanh(float x) {
    float r; asm("tanh.approx.f32 %0, %1;" : "=f"(r) : "f"(x)); return r;
}
