2593	// Allocates per-split scratch (normalized O + lse), launches prefill_kernel with grid.x = num_splits,
2594	// then dec::combine_kernel reduces across splits. num_splits auto-fills ~2 waves of CTAs, capped by
2595	// n_max (key tiles) so no split is wasted; LSEpart is pre-filled -inf so empty/early-out splits drop.
2596	// Largest stage count in [1,DS_MAX_STAGES] whose Q + STAGES*(K+V) smem fits the Hopper dynamic-smem cap
2597	// (~227KB), for a CN-wide key tile and HDsm/HDVsm-padded head dims (TC is 16-bit here). Decode uses a
2598	// single consumer WG (cm=64) so Q smem halves -> deeper K/V pipelines fit, hiding more load latency.
2599	static constexpr int DS_MAX_STAGES = 5;
2600	// occ = target CTAs/SM: occ=2 halves the smem budget so two CTAs co-reside (2x memory-level
2601	// parallelism for DRAM-latency-bound decode). Returns the deepest pipeline that fits.
2602	static constexpr int ds_fit_stages(int cn, int hdsm, int hdvsm, int cm = pf::CTA_M, int occ = 1) {
2603	    const int per = (cn * hdsm + cn * hdvsm) * 2;
2604	    const int qb  = cm * hdsm * 2;
2605	    const int budget = (227 * 1024 - 64) / occ;
2606	    int s = DS_MAX_STAGES;
2607	    while (s > 1 && qb + s * per > budget) --s;
2608	    return s;
2609	}
