    rescale_o_g(acc_o, sc);
    pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + ((n_cnt - 1) % STAGES) * stV_bytes);
    mbar_arrive(&empty[(n_cnt - 1) % STAGES]);

