    for (int r = 0; r < 2; ++r) {
        l_r[r] = quad_sum(l_r[r]);
        bool bad = (l_r[r] == 0.f || l_r[r] != l_r[r]);
        float inv = bad ? 0.f : 1.f / l_r[r];
