            const int hq = hkv * rep;
            float* op = Opart + (((long)split * total_q + qidx) * hq + qhead) * HDV;
#pragma unroll
            for (int c = 0; c < HDV / 8; ++c) {
                int dv0 = 8 * c + 2 * tg;
