        uint32_t upper0 = lane_03 ? upper : lower;
        uint32_t lower0 = lane_03 ? lower : upper;
        upper0 = __shfl_sync(0xffffffffu, upper0, src_hi, 32);
        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
