__device__ __forceinline__ void pv_fp8_rs(float (&acc_o)[64], const uint32_t (&P16)[16], uint32_t sV_base) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
