  kb = at::empty(k.sizes(), k.options().dtype(at::kBFloat16));
  vb = at::empty(v.sizes(), v.options().dtype(at::kBFloat16));
  qb = at::empty(q.sizes(), q.options().dtype(at::kBFloat16));
  long nK = k.numel(), nV = v.numel(), nQ = q.numel(), tot = nK + nV + nQ;
