static void fp8_upcast_qkv(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
                           at::Tensor& qb, at::Tensor& kb, at::Tensor& vb, cudaStream_t stream) {
  if (!(q.is_contiguous() && k.is_contiguous() && v.is_contiguous() &&
        (q.numel() % 16 == 0) && (k.numel() % 16 == 0) && (v.numel() % 16 == 0))) {
    qb = fp8_upcast_bf16(q, stream); kb = fp8_upcast_bf16(k, stream); vb = fp8_upcast_bf16(v, stream);
    return;
  }
  kb = at::empty(k.sizes(), k.options().dtype(at::kBFloat16));
  vb = at::empty(v.sizes(), v.options().dtype(at::kBFloat16));
  qb = at::empty(q.sizes(), q.options().dtype(at::kBFloat16));
  long nK = k.numel(), nV = v.numel(), nQ = q.numel(), tot = nK + nV + nQ;
  int threads = 256; long blocks = (tot / 16 + threads - 1) / threads; if (blocks < 1) blocks = 1;
  fp8_cast3<<<(unsigned)blocks, threads, 0, stream>>>(
      (const __nv_fp8_e4m3*)k.data_ptr(), (__nv_bfloat16*)kb.data_ptr(), nK,
      (const __nv_fp8_e4m3*)v.data_ptr(), (__nv_bfloat16*)vb.data_ptr(), nV,
      (const __nv_fp8_e4m3*)q.data_ptr(), (__nv_bfloat16*)qb.data_ptr(), nQ);
}

