// Vectorized fp8 e4m3 -> bf16 upcast (lossless: e4m3's 3 mantissa bits fit bf16's 7). torch's .to()
// runs a scalar 1-byte-load copy (~0.7 TB/s, 25us for a 6MB KV cache); this reads 16 fp8 per thread
// (uint4) and writes 16 bf16, hitting HBM bandwidth (~5us). Used to feed the fast bf16 TMA wgmma
// decode for hd64/hd96 fp8 (native fp8 wgmma can't compose the 128B swizzle below 128-wide rows).
__global__ void fp8_to_bf16_cast(const __nv_fp8_e4m3* __restrict__ src,
                                 __nv_bfloat16* __restrict__ dst, long n) {
  long i = ((long)blockIdx.x * blockDim.x + threadIdx.x) * 16;
  if (i + 16 <= n) {
    uint4 raw = *reinterpret_cast<const uint4*>(src + i);
    const __nv_fp8_e4m3* f = reinterpret_cast<const __nv_fp8_e4m3*>(&raw);
    __nv_bfloat16 out[16];
#pragma unroll
    for (int j = 0; j < 16; ++j) out[j] = __float2bfloat16(float(f[j]));
    reinterpret_cast<uint4*>(dst + i)[0] = reinterpret_cast<const uint4*>(out)[0];
    reinterpret_cast<uint4*>(dst + i)[1] = reinterpret_cast<const uint4*>(out)[1];
  } else if (i < n) {
    for (long j = i; j < n; ++j) dst[j] = __float2bfloat16(float(src[j]));
  }
}
// Allocate a bf16 copy of a contiguous fp8 tensor via the vectorized cast (falls back to .to() if the
// tensor isn't contiguous, which the paged KV cache always is).
static at::Tensor fp8_upcast_bf16(const at::Tensor& t, cudaStream_t stream) {
  if (!t.is_contiguous()) return t.to(at::kBFloat16);
  at::Tensor o = at::empty(t.sizes(), t.options().dtype(at::kBFloat16));
  long n = t.numel();
  if (n > 0) {
    int threads = 256; long blocks = (n / 16 + threads - 1) / threads; if (blocks < 1) blocks = 1;
    fp8_to_bf16_cast<<<(unsigned)blocks, threads, 0, stream>>>(
        (const __nv_fp8_e4m3*)t.data_ptr(), (__nv_bfloat16*)o.data_ptr(), n);
  }
  return o;
}

// Fused 3-tensor cast: upcast Q,K,V in ONE launch (each ~5us of launch overhead otherwise dominates the
// tiny decode). Segment boundaries are 16-aligned (all three numels divide 16 for the supported shapes),
// so a 16-element chunk never straddles two tensors. Each must be contiguous (paged KV always is).
__global__ void fp8_cast3(const __nv_fp8_e4m3* sK, __nv_bfloat16* dK, long nK,
                          const __nv_fp8_e4m3* sV, __nv_bfloat16* dV, long nV,
                          const __nv_fp8_e4m3* sQ, __nv_bfloat16* dQ, long nQ) {
  long g = ((long)blockIdx.x * blockDim.x + threadIdx.x) * 16;
  const __nv_fp8_e4m3* src; __nv_bfloat16* dst; long n, i;
  if      (g < nK)      { src = sK; dst = dK; n = nK; i = g; }
  else if (g < nK + nV) { src = sV; dst = dV; n = nV; i = g - nK; }
  else                  { src = sQ; dst = dQ; n = nQ; i = g - nK - nV; }
  if (i + 16 <= n) {
    uint4 raw = *reinterpret_cast<const uint4*>(src + i);
    const __nv_fp8_e4m3* f = reinterpret_cast<const __nv_fp8_e4m3*>(&raw);
    __nv_bfloat16 out[16];
#pragma unroll
    for (int j = 0; j < 16; ++j) out[j] = __float2bfloat16(float(f[j]));
    reinterpret_cast<uint4*>(dst + i)[0] = reinterpret_cast<const uint4*>(out)[0];
    reinterpret_cast<uint4*>(dst + i)[1] = reinterpret_cast<const uint4*>(out)[1];
  } else if (i < n) {
    for (long j = i; j < n; ++j) dst[j] = __float2bfloat16(float(src[j]));
  }
}
// Upcast q,k,v to bf16 in one launch when all three are contiguous (else per-tensor fallback).
static void fp8_upcast_qkv(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
                           at::Tensor& qb, at::Tensor& kb, at::Tensor& vb, cudaStream_t stream) {
  if (!(q.is_contiguous() && k.is_contiguous() && v.is_contiguous() &&
        (q.numel() % 16 == 0) && (k.numel() % 16 == 0) && (v.numel() % 16 == 0))) {
